<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaSecurityPressureQuestionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:author-subordinate-persona-security-pressure-question')]final class SenateAuthorSubordinatePersonaSecurityPressureQuestionCommand extends Command{public function __construct(private readonly SubordinatePersonaSecurityPressureQuestionService$s){parent::__construct();}protected function configure():void{$this->addArgument('governance-pressure-trial-id',InputArgument::REQUIRED);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->author((string)$i->getArgument('governance-pressure-trial-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln('<info>SECURITY_PRESSURE_QUESTION_SEALED_PENDING_TESTIMONY_AUTHORIZATION</info> '.$r['question_record_id']);return self::SUCCESS;}}
